def solve(nums: list[int]) -> int:
    """
    Calculates the length of the longest contiguous subarray with strictly increasing elements.
    """
    if not nums:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            current_length += 1
        else:
            current_length = 1

        if current_length > max_length:
            max_length = current_length

    return max_length
