def solve(s: str) -> str:
    left = 0
    counts = {}
    best_start = 0
    best_len = 0

    for right, ch in enumerate(s):
        counts[ch] = counts.get(ch, 0) + 1

        while len(counts) > 2:
            left_ch = s[left]
            counts[left_ch] -= 1
            if counts[left_ch] == 0:
                del counts[left_ch]
            left += 1

        current_len = right - left + 1
        if current_len > best_len:
            best_start = left
            best_len = current_len

    return s[best_start:best_start + best_len]
