def solve(n: int) -> list[int]:
    res = []
    p2 = 1
    while p2 <= n:
        p3 = p2
        while p3 <= n:
            p5 = p3
            while p5 <= n:
                res.append(p5)
                p5 *= 5
            p3 *= 3
        p2 *= 2
    return sorted(res)
```

