def solve(n: int) -> list[int]:
    if n < 1:
        return []
    nums = [1]
    i2 = i3 = i5 = 0
    while True:
        next2 = nums[i2] * 2
        next3 = nums[i3] * 3
        next5 = nums[i5] * 5
        next_num = min(next2, next3, next5)
        if next_num > n:
            break
        nums.append(next_num)
        if next_num == next2:
            i2 += 1
        if next_num == next3:
            i3 += 1
        if next_num == next5:
            i5 += 1
    return nums
```

