def solve(n: int) -> list[int]:
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    primes = [p for p in range(7, n + 1) if is_prime(p)]
    result = []

    for i in range(1, n + 1):
        if all(i % p != 0 for p in primes):
            result.append(i)

    return result
```

